export type CardRarity =
    | "any"
    | "basic"
    | "common"
    | "uncommon"
    | "rare"
    | "ancient"
    | "event"
    | "token"
    | "curse"
    | "status"
    | "quest"

export type CardType =
    | "any"
    | "attack"
    | "skill"
    | "power"
    | "status"
    | "curse"
    | "quest"

export type CardColor =
    | "any"
    | "ironclad"
    | "silent"
    | "regent"
    | "necrobinder"
    | "defect"
    | "colorless"

export type CardCost = number | "x" | "unplayable";

export interface CardDefinition {
    id: string;
    name: string;
    cost: number;
    is_x_cost: boolean;
    star_cost: number;
    is_x_star_cost: boolean;
    type: CardType;
    rarity: CardRarity;
    color: CardColor;
    keywords: string[] | null;
    tags: string[] | null;
}

